WITH unpacked AS (SELECT id, currency, tier_limits, tier_prices, discounts, ELEMENT_AT(tier_prices, 1) AS entry_price, SLICE(tier_limits, 1, 2) AS first_two_limits, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, AGGREGATE(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ARRAY_MIN(tier_prices) AS lowest_price FROM price_tiers WHERE currency IN ('EUR', 'USD', 'THB')) SELECT id, currency, avg_tier_price, NTILE(5) OVER (PARTITION BY currency ORDER BY entry_price DESC, id) AS entry_price_bucket, SUM(entry_price) OVER (PARTITION BY currency ORDER BY avg_tier_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_entry_price, LAG(avg_tier_price, 2) OVER w_ordered AS prev_avg_tier_price FROM unpacked WINDOW w_ordered AS (ORDER BY lowest_price, id);
